body {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    margin: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* BATCH-090: Gerenciador de arquivos por árvore física — 4 modos de visualização. */

.hidden {
    display: none;
}

.c2f-files-app .c2f-toolbar {
    margin-bottom: 0;
}

.c2f-breadcrumb {
    font-size: 1.1em;
}

.c2f-folder-tools {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
}

/* Só é flex quando visível; escondida vence o display:flex (senão o !important
   do flex sobrepõe .hidden e a barra fica sempre aparecendo). */
.c2f-selection-bar:not(.hidden) {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
}

.c2f-selection-bar.hidden {
    display: none !important;
}

.c2f-selection-bar .c2f-selection-actions {
    display: flex;
    align-items: center;
    gap: 6px;
}

.c2f-selection-bar .c2f-selection-actions button.hidden {
    display: none !important;
}

/* ===== Busca instantânea ===== */

.c2f-search-box {
    margin: 10px 0;
}

.c2f-search-box .c2f-search-clear {
    cursor: pointer;
}

.c2f-search-box i.icon.hidden {
    display: none !important;
}

.c2f-hidden-search {
    display: none !important;
}

/* ===== Lista base ===== */

.c2f-files-list {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 12px;
}

.c2f-item {
    position: relative;
    border: 1px solid rgba(34, 36, 38, .15);
    border-radius: 6px;
    background: #fff;
    box-sizing: border-box;
    transition: box-shadow .15s ease, border-color .15s ease;
}

.c2f-item:hover {
    box-shadow: 0 2px 10px rgba(0, 0, 0, .12);
    border-color: rgba(34, 36, 38, .35);
}

.c2f-item .c2f-check {
    position: absolute;
    top: 6px;
    left: 6px;
    /* Acima do overlay de ações dos modos compactos (z-index 4): marcar o item precisa continuar
       possível justamente enquanto o mouse está sobre o card. */
    z-index: 5;
    background: rgba(255, 255, 255, .85);
    border-radius: 4px;
    padding: 1px 3px;
}

.c2f-thumb {
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background: #f7f7f8;
    cursor: pointer;
}

.c2f-thumb .c2f-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.c2f-folder .c2f-thumb {
    background: #fffdf3;
}

.c2f-name {
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    cursor: pointer;
}

.c2f-sub {
    color: rgba(0, 0, 0, .5);
    font-size: .85em;
}

.c2f-actions {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
}

/* ===== Modo GRANDE (card com detalhes) ===== */

.view-large .c2f-item {
    width: calc(25% - 12px);
    padding: 10px;
}

.view-large .c2f-thumb {
    width: 100%;
    height: 160px;
    border-radius: 4px;
}

.view-large .c2f-meta {
    margin-top: 8px;
}

.view-large .c2f-actions {
    margin-top: 8px;
    justify-content: center;
}

/* ===== Modo MÉDIO (ícones médios) ===== */

.view-medium .c2f-item {
    width: calc(16.66% - 12px);
    padding: 8px;
    text-align: center;
}

.view-medium .c2f-thumb {
    width: 100%;
    height: 110px;
    border-radius: 4px;
}

.view-medium .c2f-meta {
    margin-top: 6px;
}

.view-medium .c2f-sub.c2f-col-type,
.view-medium .c2f-sub.c2f-col-size,
.view-small .c2f-sub {
    display: none;
}

/* ===== Modo PEQUENO (ícones pequenos) ===== */

.view-small .c2f-item {
    width: calc(10% - 12px);
    padding: 6px;
    text-align: center;
}

.view-small .c2f-thumb {
    width: 100%;
    height: 64px;
    border-radius: 4px;
}

.view-small .c2f-name {
    font-size: .82em;
    font-weight: 500;
}

/* ===== Overlay de ações dos modos compactos (BATCH-140) =====

   Antes, `.c2f-actions` alternava entre `display: none` e `display: flex` no hover. Como o elemento
   está NO FLUXO do card, aparecer aumentava a altura do `.c2f-item` e empurrava toda a grade: o grid
   inteiro tremia a cada passagem do mouse. Aqui a barra sai do fluxo (`position: absolute`) e cobre
   exatamente a área da miniatura, então largura e altura do card são as MESMAS com e sem hover.

   `pointer-events` fica em `none` no contêiner e só é liberado nos botões: assim a área vazia do
   overlay continua entregando o clique para a miniatura (abrir galeria / entrar na pasta) e para o
   checkbox, que é o comportamento já existente. */

.view-medium .c2f-actions,
.view-small .c2f-actions {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    background: rgba(0, 0, 0, .55);
    border-radius: 4px;
    opacity: 0;
    pointer-events: none;
    transition: opacity .15s ease-in-out;
    z-index: 4;
}

/* O overlay é ancorado no `.c2f-item` (que já é `position: relative`) e recortado sobre a miniatura:
   deslocamento igual ao padding do card, altura igual à do `.c2f-thumb` do modo. */
.view-medium .c2f-actions {
    top: 8px;
    left: 8px;
    right: 8px;
    height: 110px;
}

.view-small .c2f-actions {
    top: 6px;
    left: 6px;
    right: 6px;
    height: 64px;
}

.view-medium .c2f-item:hover .c2f-actions,
.view-medium .c2f-item:focus-within .c2f-actions,
.view-small .c2f-item:hover .c2f-actions,
.view-small .c2f-item:focus-within .c2f-actions {
    opacity: 1;
}

.view-medium .c2f-item:hover .c2f-actions button,
.view-medium .c2f-item:focus-within .c2f-actions button,
.view-small .c2f-item:hover .c2f-actions button,
.view-small .c2f-item:focus-within .c2f-actions button {
    pointer-events: auto;
}

/* Contraste dos botões sobre o fundo escuro do overlay. */
.view-medium .c2f-actions button,
.view-small .c2f-actions button {
    margin: 0;
    background: rgba(255, 255, 255, .92);
    color: rgba(0, 0, 0, .8);
    box-shadow: 0 1px 3px rgba(0, 0, 0, .35);
}

.view-medium .c2f-actions button:hover,
.view-small .c2f-actions button:hover {
    background: #fff;
    color: rgba(0, 0, 0, .95);
}

.view-medium .c2f-actions .c2f-del,
.view-small .c2f-actions .c2f-del {
    background: #db2828;
    color: #fff;
}

.view-medium .c2f-actions .c2f-del:hover,
.view-small .c2f-actions .c2f-del:hover {
    background: #d01919;
    color: #fff;
}

.view-medium .c2f-actions .c2f-select,
.view-small .c2f-actions .c2f-select {
    background: #2185d0;
    color: #fff;
}

.view-medium .c2f-actions .c2f-select:hover,
.view-small .c2f-actions .c2f-select:hover {
    background: #1678c2;
    color: #fff;
}

@media (prefers-reduced-motion: reduce) {

    .view-medium .c2f-actions,
    .view-small .c2f-actions {
        transition: none;
    }
}

/* ===== Modo LISTAGEM (tabela/linha compacta) ===== */

.view-list .c2f-files-list {
    display: block;
    gap: 0;
}

.view-list .c2f-item {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 6px 10px 6px 34px;
    border-radius: 0;
    border-bottom: none;
}

.view-list .c2f-item + .c2f-item {
    border-top: none;
}

.view-list .c2f-thumb {
    width: 40px;
    height: 40px;
    min-width: 40px;
    border-radius: 3px;
}

.view-list .c2f-meta {
    display: flex;
    flex: 1;
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.view-list .c2f-name {
    flex: 2;
    min-width: 0;
}

.view-list .c2f-sub {
    flex: 1;
    white-space: nowrap;
}

.view-list .c2f-actions {
    margin-left: auto;
}

/* Responsividade */
@media only screen and (max-width: 767px) {
    .view-large .c2f-item { width: calc(50% - 12px); }
    .view-medium .c2f-item { width: calc(33.33% - 12px); }
    .view-small .c2f-item { width: calc(25% - 12px); }
    .view-list .c2f-sub.c2f-col-type { display: none; }
}

/* ===== Galeria de imagens (modal) ===== */

.c2f-gallery-modal {
    position: relative;
    width: min(96vw, 1200px);
    max-width: none;
    max-height: 90vh;
    border: 0;
    border-radius: 6px;
    padding: 16px;
    color: #f8fafc;
    background: #101113;
}

.c2f-gallery-modal::backdrop {
    background: rgba(0, 0, 0, .72);
}

.c2f-gallery-close {
    position: absolute;
    top: 8px;
    right: 8px;
    z-index: 1;
    width: 36px;
    height: 36px;
    border: 1px solid #475569;
    border-radius: 4px;
    color: #fff;
    background: #1e293b;
}

.c2f-gallery-header {
    margin: 0 44px 12px 0;
    font-weight: 600;
}

.c2f-gallery-content {
    display: flex !important;
    align-items: center;
    justify-content: center;
    gap: 10px;
    background: #101113;
    padding: 0 !important;
}

.c2f-gallery-stage {
    flex: 1;
    text-align: center;
    min-width: 0;
    padding: 8px;
}

.c2f-gallery-img {
    max-width: 100%;
    max-height: 72vh;
    object-fit: contain;
}

.c2f-gallery-prev,
.c2f-gallery-next {
    flex: 0 0 auto;
    margin: 0 6px !important;
}

.c2f-gallery-strip {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    padding: 8px;
    background: #1b1c1d;
}

.c2f-gallery-strip img {
    height: 60px;
    width: 60px;
    object-fit: cover;
    border-radius: 4px;
    cursor: pointer;
    opacity: .5;
    border: 2px solid transparent;
    transition: opacity .15s ease;
}

.c2f-gallery-strip img:hover {
    opacity: .85;
}

.c2f-gallery-strip img.active {
    opacity: 1;
    border-color: #2185d0;
}

.c2f-gallery-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px;
    padding-top: 12px;
}

@media (max-width: 640px) {
    .c2f-gallery-content {
        min-height: 50vh;
    }

    .c2f-gallery-prev,
    .c2f-gallery-next {
        margin: 0 2px !important;
    }
}

/* ===== req-240: barra de ferramentas, busca e botões na folha do painel ===== */

.c2f-files-app {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.c2f-search-box {
    position: relative;
    margin: 0;
}

.c2f-search-box .c2f-search-icon,
.c2f-search-box .c2f-search-clear {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    color: #94a3b8;
}

.c2f-search-box .c2f-search-icon {
    left: 12px;
    pointer-events: none;
}

.c2f-search-box .c2f-search-clear {
    right: 12px;
}

.c2f-search-box .c2f-search-clear.hidden {
    display: none !important;
}

.c2f-view-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    /* REQ-243: mesma altura dos botões de ação ao lado (texto de 20 px de linha + respiro + borda). */
    min-height: 34px;
    border-color: #cbd5e1;
    background: #fff;
    color: #475569;
}

.c2f-view-btn.active {
    border-color: #0284c7;
    background: #f0f9ff;
    color: #0369a1;
}

.c2f-folder-tools > a,
.c2f-folder-tools > button,
.c2f-selection-actions button,
#c2f-move-bar button {
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

/* req-240: item selecionado fica evidente (seleção múltipla, inclusive no seletor em iframe). */
.c2f-item.c2f-selecionado {
    border-color: #0284c7;
    background: #f0f9ff;
    box-shadow: 0 0 0 2px rgba(2, 132, 199, .45);
}

.c2f-item.c2f-selecionado .c2f-check {
    background: #0284c7;
}

/* req-240: nos modos compactos as ações de hover ficam numa faixa na base da miniatura, como opções
   secundárias; o meio da imagem fica livre para o clique principal. A caixa do overlay não muda de
   tamanho (a grade continua sem tremer): só o alinhamento e o fundo. */
.view-medium .c2f-actions,
.view-small .c2f-actions {
    align-items: flex-end;
    padding-bottom: 5px;
    background: linear-gradient(to top, rgba(15, 23, 42, .62), rgba(15, 23, 42, 0) 46%);
}

/* req-240: margem do gerenciador quando aberto em iframe (seletor). Fica aqui, e não no layout de iframe,
   porque outras telas usam o mesmo layout (a barra de edição do site, por exemplo) e não podem ser empurradas. */
body.c2f-arquivos-iframe {
    margin: 0;
    padding: 16px;
    background: #f8fafc;
}

/* REQ-242: bandeja do seletor (iframe) — miniaturas do que está marcado, com remoção direta, ao lado de
   Cancelar e Incluir Selecionados. Fica presa à base do modal enquanto a lista rola. */
.c2f-pick-tray.hidden { display: none; }
.c2f-pick-tray:not(.hidden) {
    position: sticky;
    bottom: 0;
    z-index: 30;
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 12px;
    padding: 8px 12px;
    border: 1px solid #bae6fd;
    border-radius: 12px;
    background: rgba(255, 255, 255, .97);
    box-shadow: 0 -8px 20px -10px rgba(15, 23, 42, .35);
}
/* REQ-243: sem seleção, a faixa de miniaturas cede o lugar à orientação. */
.c2f-pick-tray-thumbs.hidden { display: none; }
.c2f-pick-tray-thumbs:not(.hidden) { display: flex; flex: 1; min-width: 0; gap: 10px; overflow-x: auto; padding: 8px 4px 4px; scrollbar-width: thin; }
.c2f-pick-thumb { position: relative; flex: none; width: 56px; height: 56px; border: 1px solid #cbd5e1; border-radius: 8px; background: #f1f5f9; }
.c2f-pick-thumb img { display: block; width: 100%; height: 100%; border-radius: 7px; object-fit: cover; }
.c2f-pick-thumb-remove { position: absolute; top: -7px; right: -7px; display: flex; align-items: center; justify-content: center; width: 20px; height: 20px; border: 2px solid #fff; border-radius: 50%; background: #0f172a; color: #fff; font: 700 13px/1 system-ui, sans-serif; cursor: pointer; }
.c2f-pick-thumb-remove:hover, .c2f-pick-thumb-remove:focus-visible { background: #dc2626; }
@media (max-width: 520px) {
    .c2f-pick-tray:not(.hidden) { flex-direction: column; align-items: stretch; }
}

/* REQ-243 (pente fino): galeria da imagem. A caixa é um <dialog> modal: com `position: relative` ela perdia a
   centralização do navegador e ficava no canto. O texto claro da caixa escura vazava para os botões brancos
   (texto e ícone invisíveis); cada botão passa a ter cor própria. */
.c2f-gallery-modal {
    position: fixed;
    inset: 0;
    margin: auto;
    height: fit-content;
    border-radius: 12px;
    overflow: auto;
}
.c2f-gallery-close,
.c2f-gallery-prev,
.c2f-gallery-next {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    padding: 0;
    border: 1px solid #475569;
    border-radius: 999px;
    background: #1e293b;
    color: #f8fafc;
    cursor: pointer;
}
.c2f-gallery-close { font-size: 22px; line-height: 1; }
.c2f-gallery-close:hover,
.c2f-gallery-prev:hover,
.c2f-gallery-next:hover { border-color: #94a3b8; background: #334155; }
.c2f-gallery-prev svg,
.c2f-gallery-next svg { width: 20px; height: 20px; }
.c2f-gallery-actions > button,
.c2f-gallery-actions > a {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #0f172a;
    text-decoration: none;
    cursor: pointer;
}
.c2f-gallery-actions > .c2f-gal-select,
.c2f-gallery-actions > .c2f-gal-del { color: #fff; }
.c2f-gallery-actions svg { width: 16px; height: 16px; flex: none; }
/* A imagem fica no meio do palco e cede altura para o título, as miniaturas e as ações caberem na caixa. */
.c2f-gallery-stage { display: flex; align-items: center; justify-content: center; }
.c2f-gallery-img { display: block; margin: 0 auto; max-height: calc(90vh - 270px); }

/* BATCH-090: Upload com drag & drop, destino e tamanho de pré-visualização.
   O tamanho selecionado reorganiza o cartão inteiro (thumb, detalhes e botões),
   espelhando os modos de visualização da listagem. */

input[type="file"] {
    opacity: 0;
    z-index: -1;
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
}

.hidden {
    display: none;
}

/* ===== Dropzone ===== */

.c2f-dropzone {
    border: 2px dashed rgba(34, 36, 38, .25);
    border-radius: 8px;
    padding: 24px;
    text-align: center;
    transition: background .15s ease, border-color .15s ease;
}

.c2f-dropzone.c2f-drag {
    border-color: #2185d0;
    background: rgba(33, 133, 208, .06);
}

.c2f-dropzone i {
    color: rgba(0, 0, 0, .35);
}

.c2f-destination .c2f-dest-label {
    max-width: 60%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* ===== Seletor de tamanho de pré-visualização ===== */

.c2f-preview-size-label {
    font-size: .7em;
    color: rgba(0, 0, 0, .5);
    vertical-align: middle;
    margin-right: 4px;
}

/* ===== Grade de cartões de upload ===== */

#files-cont {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 20px;
    align-items: flex-start;
}

.c2f-upload-cel {
    box-sizing: border-box;
    margin: 0 !important;
    display: flex;
    flex-direction: column;
}

.c2f-upload-thumb {
    text-align: center;
}

.c2f-upload-image {
    display: inline-block;
    margin: 0 auto;
    object-fit: cover;
    border-radius: 4px;
}

.c2f-upload-body {
    min-width: 0;
}

.c2f-upload-name {
    font-weight: 600;
    margin: 8px 0 4px;
    word-break: break-word;
}

.c2f-upload-details {
    margin: 0 0 8px !important;
    width: 100%;
    border-collapse: collapse;
}

.c2f-upload-details td {
    padding: 2px 6px !important;
    border: none !important;
}

.c2f-upload-details td:first-child {
    color: rgba(0, 0, 0, .5);
    white-space: nowrap;
}

.c2f-upload-buttons button {
    margin: 0 2px 4px;
}

.c2f-progress {
    height: 16px;
    overflow: hidden;
    border-radius: 999px;
    background: #e2e8f0;
}

.c2f-progress .bar {
    width: 0;
    height: 100%;
    overflow: hidden;
    background: #0e7490;
    transition: width .15s ease;
}

.c2f-progress .progress {
    display: block;
    overflow: hidden;
    padding-right: 6px;
    color: #fff;
    font-size: .7rem;
    line-height: 16px;
    text-align: right;
    white-space: nowrap;
}

.c2f-progress-error .bar {
    background: #be123c;
}

.c2f-progress-indeterminate .bar {
    width: 36%;
    animation: c2f-upload-progress 1.4s ease-in-out infinite alternate;
}

@keyframes c2f-upload-progress {
    from { transform: translateX(0); }
    to { transform: translateX(180%); }
}

/* --- XL: 1 por linha, thumb grande à esquerda, corpo à direita --- */
#files-cont.preview-xl .c2f-upload-cel { width: 100%; flex-direction: row; gap: 16px; align-items: flex-start; }
#files-cont.preview-xl .c2f-upload-thumb { flex: 0 0 340px; }
#files-cont.preview-xl .c2f-upload-image { width: 100%; height: auto; max-height: 420px; }
#files-cont.preview-xl .c2f-upload-body { flex: 1; }

/* --- L: 2 por linha, thumb média à esquerda --- */
#files-cont.preview-l .c2f-upload-cel { width: calc(50% - 12px); flex-direction: row; gap: 14px; align-items: flex-start; }
#files-cont.preview-l .c2f-upload-thumb { flex: 0 0 190px; }
#files-cont.preview-l .c2f-upload-image { width: 190px; height: 190px; }
#files-cont.preview-l .c2f-upload-body { flex: 1; }

/* --- M: ~4 por linha, vertical, detalhes reduzidos (só tamanho) --- */
#files-cont.preview-m .c2f-upload-cel { width: calc(25% - 12px); }
#files-cont.preview-m .c2f-upload-image { width: 100%; height: 160px; }
#files-cont.preview-m .c2f-upload-details tr:nth-child(1),
#files-cont.preview-m .c2f-upload-details tr:nth-child(3) { display: none; }
#files-cont.preview-m .c2f-upload-buttons button { font-size: .85rem; }

/* --- S: ~6 por linha, mínimo: thumb + nome + botões (sem tabela de detalhes) --- */
#files-cont.preview-s .c2f-upload-cel { width: calc(16.66% - 12px); padding: 8px !important; }
#files-cont.preview-s .c2f-upload-image { width: 100%; height: 100px; }
#files-cont.preview-s .c2f-upload-details { display: none; }
#files-cont.preview-s .c2f-upload-name { font-size: .82em; margin: 6px 0 2px; }
#files-cont.preview-s .c2f-upload-buttons button { font-size: .72rem; padding: .5em .7em; margin: 0 1px 3px; }

/* Responsividade */
@media only screen and (max-width: 991px) {
    #files-cont.preview-m .c2f-upload-cel { width: calc(33.33% - 12px); }
    #files-cont.preview-s .c2f-upload-cel { width: calc(25% - 12px); }
}

@media only screen and (max-width: 767px) {
    #files-cont.preview-l .c2f-upload-cel,
    #files-cont.preview-xl .c2f-upload-cel { width: 100%; flex-direction: column; }
    #files-cont.preview-l .c2f-upload-thumb,
    #files-cont.preview-xl .c2f-upload-thumb { flex: none; }
    #files-cont.preview-l .c2f-upload-image,
    #files-cont.preview-xl .c2f-upload-image { width: 100%; height: auto; }
    #files-cont.preview-m .c2f-upload-cel,
    #files-cont.preview-s .c2f-upload-cel { width: calc(50% - 12px); }
}

/* req-240: margem do gerenciador quando aberto em iframe (seletor). */
body.c2f-arquivos-iframe {
    margin: 0;
    padding: 16px;
    background: #f8fafc;
}

/* BATCH-090: Gerenciador de arquivos por árvore física — 4 modos de visualização. */

.hidden {
    display: none;
}

.c2f-files-app .c2f-toolbar {
    margin-bottom: 0;
}

.c2f-breadcrumb {
    font-size: 1.1em;
}

.c2f-folder-tools {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
}

/* Só é flex quando visível; escondida vence o display:flex (senão o !important
   do flex sobrepõe .hidden e a barra fica sempre aparecendo). */
.c2f-selection-bar:not(.hidden) {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
}

.c2f-selection-bar.hidden {
    display: none !important;
}

.c2f-selection-bar .c2f-selection-actions {
    display: flex;
    align-items: center;
    gap: 6px;
}

.c2f-selection-bar .c2f-selection-actions button.hidden {
    display: none !important;
}

/* ===== Busca instantânea ===== */

.c2f-search-box {
    margin: 10px 0;
}

.c2f-search-box .c2f-search-clear {
    cursor: pointer;
}

.c2f-search-box i.icon.hidden {
    display: none !important;
}

.c2f-hidden-search {
    display: none !important;
}

/* ===== Lista base ===== */

.c2f-files-list {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 12px;
}

.c2f-item {
    position: relative;
    border: 1px solid rgba(34, 36, 38, .15);
    border-radius: 6px;
    background: #fff;
    box-sizing: border-box;
    transition: box-shadow .15s ease, border-color .15s ease;
}

.c2f-item:hover {
    box-shadow: 0 2px 10px rgba(0, 0, 0, .12);
    border-color: rgba(34, 36, 38, .35);
}

.c2f-item .c2f-check {
    position: absolute;
    top: 6px;
    left: 6px;
    /* Acima do overlay de ações dos modos compactos (z-index 4): marcar o item precisa continuar
       possível justamente enquanto o mouse está sobre o card. */
    z-index: 5;
    background: rgba(255, 255, 255, .85);
    border-radius: 4px;
    padding: 1px 3px;
}

.c2f-thumb {
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background: #f7f7f8;
    cursor: pointer;
}

.c2f-thumb .c2f-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.c2f-folder .c2f-thumb {
    background: #fffdf3;
}

.c2f-name {
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    cursor: pointer;
}

.c2f-sub {
    color: rgba(0, 0, 0, .5);
    font-size: .85em;
}

.c2f-actions {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
}

/* ===== Modo GRANDE (card com detalhes) ===== */

.view-large .c2f-item {
    width: calc(25% - 12px);
    padding: 10px;
}

.view-large .c2f-thumb {
    width: 100%;
    height: 160px;
    border-radius: 4px;
}

.view-large .c2f-meta {
    margin-top: 8px;
}

.view-large .c2f-actions {
    margin-top: 8px;
    justify-content: center;
}

/* ===== Modo MÉDIO (ícones médios) ===== */

.view-medium .c2f-item {
    width: calc(16.66% - 12px);
    padding: 8px;
    text-align: center;
}

.view-medium .c2f-thumb {
    width: 100%;
    height: 110px;
    border-radius: 4px;
}

.view-medium .c2f-meta {
    margin-top: 6px;
}

.view-medium .c2f-sub.c2f-col-type,
.view-medium .c2f-sub.c2f-col-size,
.view-small .c2f-sub {
    display: none;
}

/* ===== Modo PEQUENO (ícones pequenos) ===== */

.view-small .c2f-item {
    width: calc(10% - 12px);
    padding: 6px;
    text-align: center;
}

.view-small .c2f-thumb {
    width: 100%;
    height: 64px;
    border-radius: 4px;
}

.view-small .c2f-name {
    font-size: .82em;
    font-weight: 500;
}

/* ===== Overlay de ações dos modos compactos (BATCH-140) =====

   Antes, `.c2f-actions` alternava entre `display: none` e `display: flex` no hover. Como o elemento
   está NO FLUXO do card, aparecer aumentava a altura do `.c2f-item` e empurrava toda a grade: o grid
   inteiro tremia a cada passagem do mouse. Aqui a barra sai do fluxo (`position: absolute`) e cobre
   exatamente a área da miniatura, então largura e altura do card são as MESMAS com e sem hover.

   `pointer-events` fica em `none` no contêiner e só é liberado nos botões: assim a área vazia do
   overlay continua entregando o clique para a miniatura (abrir galeria / entrar na pasta) e para o
   checkbox, que é o comportamento já existente. */

.view-medium .c2f-actions,
.view-small .c2f-actions {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    background: rgba(0, 0, 0, .55);
    border-radius: 4px;
    opacity: 0;
    pointer-events: none;
    transition: opacity .15s ease-in-out;
    z-index: 4;
}

/* O overlay é ancorado no `.c2f-item` (que já é `position: relative`) e recortado sobre a miniatura:
   deslocamento igual ao padding do card, altura igual à do `.c2f-thumb` do modo. */
.view-medium .c2f-actions {
    top: 8px;
    left: 8px;
    right: 8px;
    height: 110px;
}

.view-small .c2f-actions {
    top: 6px;
    left: 6px;
    right: 6px;
    height: 64px;
}

.view-medium .c2f-item:hover .c2f-actions,
.view-medium .c2f-item:focus-within .c2f-actions,
.view-small .c2f-item:hover .c2f-actions,
.view-small .c2f-item:focus-within .c2f-actions {
    opacity: 1;
}

.view-medium .c2f-item:hover .c2f-actions button,
.view-medium .c2f-item:focus-within .c2f-actions button,
.view-small .c2f-item:hover .c2f-actions button,
.view-small .c2f-item:focus-within .c2f-actions button {
    pointer-events: auto;
}

/* Contraste dos botões sobre o fundo escuro do overlay. */
.view-medium .c2f-actions button,
.view-small .c2f-actions button {
    margin: 0;
    background: rgba(255, 255, 255, .92);
    color: rgba(0, 0, 0, .8);
    box-shadow: 0 1px 3px rgba(0, 0, 0, .35);
}

.view-medium .c2f-actions button:hover,
.view-small .c2f-actions button:hover {
    background: #fff;
    color: rgba(0, 0, 0, .95);
}

.view-medium .c2f-actions .c2f-del,
.view-small .c2f-actions .c2f-del {
    background: #db2828;
    color: #fff;
}

.view-medium .c2f-actions .c2f-del:hover,
.view-small .c2f-actions .c2f-del:hover {
    background: #d01919;
    color: #fff;
}

.view-medium .c2f-actions .c2f-select,
.view-small .c2f-actions .c2f-select {
    background: #2185d0;
    color: #fff;
}

.view-medium .c2f-actions .c2f-select:hover,
.view-small .c2f-actions .c2f-select:hover {
    background: #1678c2;
    color: #fff;
}

@media (prefers-reduced-motion: reduce) {

    .view-medium .c2f-actions,
    .view-small .c2f-actions {
        transition: none;
    }
}

/* ===== Modo LISTAGEM (tabela/linha compacta) ===== */

.view-list .c2f-files-list {
    display: block;
    gap: 0;
}

.view-list .c2f-item {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 6px 10px 6px 34px;
    border-radius: 0;
    border-bottom: none;
}

.view-list .c2f-item + .c2f-item {
    border-top: none;
}

.view-list .c2f-thumb {
    width: 40px;
    height: 40px;
    min-width: 40px;
    border-radius: 3px;
}

.view-list .c2f-meta {
    display: flex;
    flex: 1;
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.view-list .c2f-name {
    flex: 2;
    min-width: 0;
}

.view-list .c2f-sub {
    flex: 1;
    white-space: nowrap;
}

.view-list .c2f-actions {
    margin-left: auto;
}

/* Responsividade */
@media only screen and (max-width: 767px) {
    .view-large .c2f-item { width: calc(50% - 12px); }
    .view-medium .c2f-item { width: calc(33.33% - 12px); }
    .view-small .c2f-item { width: calc(25% - 12px); }
    .view-list .c2f-sub.c2f-col-type { display: none; }
}

/* ===== Galeria de imagens (modal) ===== */

.c2f-gallery-modal {
    position: relative;
    width: min(96vw, 1200px);
    max-width: none;
    max-height: 90vh;
    border: 0;
    border-radius: 6px;
    padding: 16px;
    color: #f8fafc;
    background: #101113;
}

.c2f-gallery-modal::backdrop {
    background: rgba(0, 0, 0, .72);
}

.c2f-gallery-close {
    position: absolute;
    top: 8px;
    right: 8px;
    z-index: 1;
    width: 36px;
    height: 36px;
    border: 1px solid #475569;
    border-radius: 4px;
    color: #fff;
    background: #1e293b;
}

.c2f-gallery-header {
    margin: 0 44px 12px 0;
    font-weight: 600;
}

.c2f-gallery-content {
    display: flex !important;
    align-items: center;
    justify-content: center;
    gap: 10px;
    background: #101113;
    padding: 0 !important;
}

.c2f-gallery-stage {
    flex: 1;
    text-align: center;
    min-width: 0;
    padding: 8px;
}

.c2f-gallery-img {
    max-width: 100%;
    max-height: 72vh;
    object-fit: contain;
}

.c2f-gallery-prev,
.c2f-gallery-next {
    flex: 0 0 auto;
    margin: 0 6px !important;
}

.c2f-gallery-strip {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    padding: 8px;
    background: #1b1c1d;
}

.c2f-gallery-strip img {
    height: 60px;
    width: 60px;
    object-fit: cover;
    border-radius: 4px;
    cursor: pointer;
    opacity: .5;
    border: 2px solid transparent;
    transition: opacity .15s ease;
}

.c2f-gallery-strip img:hover {
    opacity: .85;
}

.c2f-gallery-strip img.active {
    opacity: 1;
    border-color: #2185d0;
}

.c2f-gallery-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px;
    padding-top: 12px;
}

@media (max-width: 640px) {
    .c2f-gallery-content {
        min-height: 50vh;
    }

    .c2f-gallery-prev,
    .c2f-gallery-next {
        margin: 0 2px !important;
    }
}

/* ===== req-240: barra de ferramentas, busca e botões na folha do painel ===== */

.c2f-files-app {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.c2f-search-box {
    position: relative;
    margin: 0;
}

.c2f-search-box .c2f-search-icon,
.c2f-search-box .c2f-search-clear {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    color: #94a3b8;
}

.c2f-search-box .c2f-search-icon {
    left: 12px;
    pointer-events: none;
}

.c2f-search-box .c2f-search-clear {
    right: 12px;
}

.c2f-search-box .c2f-search-clear.hidden {
    display: none !important;
}

.c2f-view-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    /* REQ-243: mesma altura dos botões de ação ao lado (texto de 20 px de linha + respiro + borda). */
    min-height: 34px;
    border-color: #cbd5e1;
    background: #fff;
    color: #475569;
}

.c2f-view-btn.active {
    border-color: #0284c7;
    background: #f0f9ff;
    color: #0369a1;
}

.c2f-folder-tools > a,
.c2f-folder-tools > button,
.c2f-selection-actions button,
#c2f-move-bar button {
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

/* req-240: item selecionado fica evidente (seleção múltipla, inclusive no seletor em iframe). */
.c2f-item.c2f-selecionado {
    border-color: #0284c7;
    background: #f0f9ff;
    box-shadow: 0 0 0 2px rgba(2, 132, 199, .45);
}

.c2f-item.c2f-selecionado .c2f-check {
    background: #0284c7;
}

/* req-240: nos modos compactos as ações de hover ficam numa faixa na base da miniatura, como opções
   secundárias; o meio da imagem fica livre para o clique principal. A caixa do overlay não muda de
   tamanho (a grade continua sem tremer): só o alinhamento e o fundo. */
.view-medium .c2f-actions,
.view-small .c2f-actions {
    align-items: flex-end;
    padding-bottom: 5px;
    background: linear-gradient(to top, rgba(15, 23, 42, .62), rgba(15, 23, 42, 0) 46%);
}

/* req-240: margem do gerenciador quando aberto em iframe (seletor). Fica aqui, e não no layout de iframe,
   porque outras telas usam o mesmo layout (a barra de edição do site, por exemplo) e não podem ser empurradas. */
body.c2f-arquivos-iframe {
    margin: 0;
    padding: 16px;
    background: #f8fafc;
}

/* REQ-242: bandeja do seletor (iframe) — miniaturas do que está marcado, com remoção direta, ao lado de
   Cancelar e Incluir Selecionados. Fica presa à base do modal enquanto a lista rola. */
.c2f-pick-tray.hidden { display: none; }
.c2f-pick-tray:not(.hidden) {
    position: sticky;
    bottom: 0;
    z-index: 30;
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 12px;
    padding: 8px 12px;
    border: 1px solid #bae6fd;
    border-radius: 12px;
    background: rgba(255, 255, 255, .97);
    box-shadow: 0 -8px 20px -10px rgba(15, 23, 42, .35);
}
/* REQ-243: sem seleção, a faixa de miniaturas cede o lugar à orientação. */
.c2f-pick-tray-thumbs.hidden { display: none; }
.c2f-pick-tray-thumbs:not(.hidden) { display: flex; flex: 1; min-width: 0; gap: 10px; overflow-x: auto; padding: 8px 4px 4px; scrollbar-width: thin; }
.c2f-pick-thumb { position: relative; flex: none; width: 56px; height: 56px; border: 1px solid #cbd5e1; border-radius: 8px; background: #f1f5f9; }
.c2f-pick-thumb img { display: block; width: 100%; height: 100%; border-radius: 7px; object-fit: cover; }
.c2f-pick-thumb-remove { position: absolute; top: -7px; right: -7px; display: flex; align-items: center; justify-content: center; width: 20px; height: 20px; border: 2px solid #fff; border-radius: 50%; background: #0f172a; color: #fff; font: 700 13px/1 system-ui, sans-serif; cursor: pointer; }
.c2f-pick-thumb-remove:hover, .c2f-pick-thumb-remove:focus-visible { background: #dc2626; }
@media (max-width: 520px) {
    .c2f-pick-tray:not(.hidden) { flex-direction: column; align-items: stretch; }
}

/* REQ-243 (pente fino): galeria da imagem. A caixa é um <dialog> modal: com `position: relative` ela perdia a
   centralização do navegador e ficava no canto. O texto claro da caixa escura vazava para os botões brancos
   (texto e ícone invisíveis); cada botão passa a ter cor própria. */
.c2f-gallery-modal {
    position: fixed;
    inset: 0;
    margin: auto;
    height: fit-content;
    border-radius: 12px;
    overflow: auto;
}
.c2f-gallery-close,
.c2f-gallery-prev,
.c2f-gallery-next {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    padding: 0;
    border: 1px solid #475569;
    border-radius: 999px;
    background: #1e293b;
    color: #f8fafc;
    cursor: pointer;
}
.c2f-gallery-close { font-size: 22px; line-height: 1; }
.c2f-gallery-close:hover,
.c2f-gallery-prev:hover,
.c2f-gallery-next:hover { border-color: #94a3b8; background: #334155; }
.c2f-gallery-prev svg,
.c2f-gallery-next svg { width: 20px; height: 20px; }
.c2f-gallery-actions > button,
.c2f-gallery-actions > a {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #0f172a;
    text-decoration: none;
    cursor: pointer;
}
.c2f-gallery-actions > .c2f-gal-select,
.c2f-gallery-actions > .c2f-gal-del { color: #fff; }
.c2f-gallery-actions svg { width: 16px; height: 16px; flex: none; }
/* A imagem fica no meio do palco e cede altura para o título, as miniaturas e as ações caberem na caixa. */
.c2f-gallery-stage { display: flex; align-items: center; justify-content: center; }
.c2f-gallery-img { display: block; margin: 0 auto; max-height: calc(90vh - 270px); }

/* BATCH-090: Upload com drag & drop, destino e tamanho de pré-visualização.
   O tamanho selecionado reorganiza o cartão inteiro (thumb, detalhes e botões),
   espelhando os modos de visualização da listagem. */

input[type="file"] {
    opacity: 0;
    z-index: -1;
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
}

.hidden {
    display: none;
}

/* ===== Dropzone ===== */

.c2f-dropzone {
    border: 2px dashed rgba(34, 36, 38, .25);
    border-radius: 8px;
    padding: 24px;
    text-align: center;
    transition: background .15s ease, border-color .15s ease;
}

.c2f-dropzone.c2f-drag {
    border-color: #2185d0;
    background: rgba(33, 133, 208, .06);
}

.c2f-dropzone i {
    color: rgba(0, 0, 0, .35);
}

.c2f-destination .c2f-dest-label {
    max-width: 60%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* ===== Seletor de tamanho de pré-visualização ===== */

.c2f-preview-size-label {
    font-size: .7em;
    color: rgba(0, 0, 0, .5);
    vertical-align: middle;
    margin-right: 4px;
}

/* ===== Grade de cartões de upload ===== */

#files-cont {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 20px;
    align-items: flex-start;
}

.c2f-upload-cel {
    box-sizing: border-box;
    margin: 0 !important;
    display: flex;
    flex-direction: column;
}

.c2f-upload-thumb {
    text-align: center;
}

.c2f-upload-image {
    display: inline-block;
    margin: 0 auto;
    object-fit: cover;
    border-radius: 4px;
}

.c2f-upload-body {
    min-width: 0;
}

.c2f-upload-name {
    font-weight: 600;
    margin: 8px 0 4px;
    word-break: break-word;
}

.c2f-upload-details {
    margin: 0 0 8px !important;
    width: 100%;
    border-collapse: collapse;
}

.c2f-upload-details td {
    padding: 2px 6px !important;
    border: none !important;
}

.c2f-upload-details td:first-child {
    color: rgba(0, 0, 0, .5);
    white-space: nowrap;
}

.c2f-upload-buttons button {
    margin: 0 2px 4px;
}

.c2f-progress {
    height: 16px;
    overflow: hidden;
    border-radius: 999px;
    background: #e2e8f0;
}

.c2f-progress .bar {
    width: 0;
    height: 100%;
    overflow: hidden;
    background: #0e7490;
    transition: width .15s ease;
}

.c2f-progress .progress {
    display: block;
    overflow: hidden;
    padding-right: 6px;
    color: #fff;
    font-size: .7rem;
    line-height: 16px;
    text-align: right;
    white-space: nowrap;
}

.c2f-progress-error .bar {
    background: #be123c;
}

.c2f-progress-indeterminate .bar {
    width: 36%;
    animation: c2f-upload-progress 1.4s ease-in-out infinite alternate;
}

@keyframes c2f-upload-progress {
    from { transform: translateX(0); }
    to { transform: translateX(180%); }
}

/* --- XL: 1 por linha, thumb grande à esquerda, corpo à direita --- */
#files-cont.preview-xl .c2f-upload-cel { width: 100%; flex-direction: row; gap: 16px; align-items: flex-start; }
#files-cont.preview-xl .c2f-upload-thumb { flex: 0 0 340px; }
#files-cont.preview-xl .c2f-upload-image { width: 100%; height: auto; max-height: 420px; }
#files-cont.preview-xl .c2f-upload-body { flex: 1; }

/* --- L: 2 por linha, thumb média à esquerda --- */
#files-cont.preview-l .c2f-upload-cel { width: calc(50% - 12px); flex-direction: row; gap: 14px; align-items: flex-start; }
#files-cont.preview-l .c2f-upload-thumb { flex: 0 0 190px; }
#files-cont.preview-l .c2f-upload-image { width: 190px; height: 190px; }
#files-cont.preview-l .c2f-upload-body { flex: 1; }

/* --- M: ~4 por linha, vertical, detalhes reduzidos (só tamanho) --- */
#files-cont.preview-m .c2f-upload-cel { width: calc(25% - 12px); }
#files-cont.preview-m .c2f-upload-image { width: 100%; height: 160px; }
#files-cont.preview-m .c2f-upload-details tr:nth-child(1),
#files-cont.preview-m .c2f-upload-details tr:nth-child(3) { display: none; }
#files-cont.preview-m .c2f-upload-buttons button { font-size: .85rem; }

/* --- S: ~6 por linha, mínimo: thumb + nome + botões (sem tabela de detalhes) --- */
#files-cont.preview-s .c2f-upload-cel { width: calc(16.66% - 12px); padding: 8px !important; }
#files-cont.preview-s .c2f-upload-image { width: 100%; height: 100px; }
#files-cont.preview-s .c2f-upload-details { display: none; }
#files-cont.preview-s .c2f-upload-name { font-size: .82em; margin: 6px 0 2px; }
#files-cont.preview-s .c2f-upload-buttons button { font-size: .72rem; padding: .5em .7em; margin: 0 1px 3px; }

/* Responsividade */
@media only screen and (max-width: 991px) {
    #files-cont.preview-m .c2f-upload-cel { width: calc(33.33% - 12px); }
    #files-cont.preview-s .c2f-upload-cel { width: calc(25% - 12px); }
}

@media only screen and (max-width: 767px) {
    #files-cont.preview-l .c2f-upload-cel,
    #files-cont.preview-xl .c2f-upload-cel { width: 100%; flex-direction: column; }
    #files-cont.preview-l .c2f-upload-thumb,
    #files-cont.preview-xl .c2f-upload-thumb { flex: none; }
    #files-cont.preview-l .c2f-upload-image,
    #files-cont.preview-xl .c2f-upload-image { width: 100%; height: auto; }
    #files-cont.preview-m .c2f-upload-cel,
    #files-cont.preview-s .c2f-upload-cel { width: calc(50% - 12px); }
}

